const pins = (filled, { accent } = {}) => `<div class="m-pins">${[0, 1, 2, 3].map((i) => `<span class="m-pin${i < filled ? ' on' : ''}" style="${accent ? 'border-color:var(--color-text-muted);width:14px;height:14px;border-width:1.5px' : ''}${accent && i < filled ? ';background:var(--color-accent);border-color:var(--color-accent)' : ''}"></span>`).join('')}</div>`;

