const stepTitle = (title, caption) => `<div style="padding-top:24px">${text(title, { size: 'xl', bold: true })}<div style="height:8px"></div>${text(caption, { size: 's', tone: 'secondary', style: 'display:block;max-width:300px' })}</div>`;
const onboardingFoot = (label, { note } = {}) => `<div style="margin-top:auto;padding:16px 20px;display:flex;flex-direction:column;gap:12px">${note ? text(note, { size: 'xs', tone: 'muted' }) : ''}${btn(label)}</div>`;

