const parseRoadmap = () => {
  const lanes = {};
  let lane;
  let group;
  let entry;
  const source = read('ROADMAP.md');
  for (const line of source.slice(source.indexOf('\n## Queue')).split('\n')) {
    const h2 = line.match(/^## (.+)$/);
    if (h2) {
      lane = h2[1].replace(/ —.*$/, '');
      lanes[lane] = { entries: [], rows: [] };
      group = undefined;
      entry = undefined;
      continue;
    }
    if (!lane) continue;
    const h3 = line.match(/^### (.+)$/);
    if (h3) {
      group = h3[1];
      continue;
    }
    const head = line.match(/^- \*\*([A-Z][A-Z0-9-]+)\*\* — (.+)$/);
    if (head) {
      entry = { id: head[1], title: head[2], group, meta: '', accept: '' };
      lanes[lane].entries.push(entry);
      continue;
    }
    if (entry && /^\s{2}`/.test(line)) entry.meta = line.trim().replace(/`/g, '');
    else if (entry && /^\s{2}accept: /.test(line)) entry.accept = line.trim().slice(8);
    else if (entry && /^\s{2}\S/.test(line) && entry.accept) entry.accept += ` ${line.trim()}`;
    else if (line.startsWith('| ') && !line.startsWith('| Decision') && !line.startsWith('| ---')) {
      lanes[lane].rows.push(line.split('|').slice(1, -1).map((cell) => cell.trim()));
    }
  }
  return lanes;
};

